import {validReminder} from './dates.mjs';
export const KEY='mis-notas-v1';
export const seed=()=>({revision:0,composer:{text:'',category:'particular'},tasks:[]});
export function valid(s){return !!s&&Number.isInteger(s.revision)&&s.revision>=0&&s.composer&&typeof s.composer.text==='string'&&['particular','trabajo'].includes(s.composer.category)&&Array.isArray(s.tasks)&&s.tasks.every(t=>t&&typeof t.id==='string'&&typeof t.text==='string'&&t.text.trim()&&['particular','trabajo'].includes(t.category)&&typeof t.done==='boolean'&&validReminder(t.reminder))&&new Set(s.tasks.map(t=>t.id)).size===s.tasks.length;}
export function read(storage){const raw=storage.getItem(KEY);const s=raw===null?seed():JSON.parse(raw);if(!valid(s))throw Error('La lista guardada no es válida. No se sobrescribirá.');return s;}
export function save(storage,next,base){const current=read(storage);if(JSON.stringify(current)!==JSON.stringify(base))throw Error('La lista cambió en otra pestaña. Exporta tu borrador y vuelve a abrir la app para revisarlo.');if(!valid(next))throw Error('La lista no es válida.');const raw=JSON.stringify(next);storage.setItem(KEY,raw);if(storage.getItem(KEY)!==raw)throw Error('No se ha podido verificar el guardado.');return next;}
export function parse(text,category='particular',id=()=>crypto.randomUUID()){let current=category;return text.split(/[\n,;]+/).flatMap(part=>{part=part.trim();const prefix=part.match(/^(trabajo|particular)\s*:\s*/i);if(prefix){current=prefix[1].toLowerCase();part=part.slice(prefix[0].length).trim();}if(!part)return [];const corrections={'leche':'Leche','agua':'Agua','limones':'Limones','comprar tieerra':'Comprar tierra','llamar al bibero':'Llamar al vivero'};return [{id:id(),text:corrections[part.toLowerCase()]||part,category:current,done:false}];});}
